package at.hausgarten.service;

import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;
import java.util.zip.*;

/** UTF8 analysis files plus exact originals. Caller must obtain explicit plaintext-export consent. */
final class BackupPortableFormat {
    interface AdditionalJson {void write(Writer output)throws Exception;}
    static JSONObject write(OutputStream destination,JSONObject canonical,JSONObject metadata,List<EncryptedBackupArchive.Source> originals,AdditionalJson namespace)throws Exception {return write(destination,canonical,metadata,originals,namespace,Collections.emptyMap());}
    static JSONObject write(OutputStream destination,JSONObject canonical,JSONObject metadata,List<EncryptedBackupArchive.Source> originals,AdditionalJson namespace,Map<String,JSONArray> additionalCsv)throws Exception {
        JSONArray entries=new JSONArray();try(ZipOutputStream zip=new ZipOutputStream(destination,StandardCharsets.UTF_8)){
            zip.setLevel(Deflater.NO_COMPRESSION);
            text(zip,"business.json",new JSONObject().put("formatVersion",1).put("applicationId","at.hausgarten.service").put("business",canonical).toString(),entries);
            for(String group:new String[]{"customers","orders","worklogs","invoices","photos","offers","appointments","service_catalog"}){JSONArray rows=canonical.optJSONArray(group);if(rows!=null)text(zip,"csv/"+group+".csv",csv(rows),entries);}
            for(String name:new TreeSet<>(additionalCsv.keySet())){if(!name.matches("[a-z][a-z0-9_]{0,80}"))throw new IOException("PORTABLE_COLLECTION_NAME_INVALID");text(zip,"csv/local_"+name+".csv",csv(additionalCsv.get(name)),entries);}
            MessageDigest digest=MessageDigest.getInstance("SHA-256");long[] count={0};ZipEntry domain=new ZipEntry("revier.json");domain.setTime(0);zip.putNextEntry(domain);
            OutputStream nonClosing=new FilterOutputStream(zip){@Override public void write(byte[] b,int o,int n)throws IOException{out.write(b,o,n);digest.update(b,o,n);count[0]+=n;}@Override public void write(int value)throws IOException{out.write(value);digest.update((byte)value);count[0]++;}@Override public void close()throws IOException{flush();}};
            Writer writer=new OutputStreamWriter(nonClosing,StandardCharsets.UTF_8);namespace.write(writer);writer.flush();zip.closeEntry();entries.put(new JSONObject().put("path","revier.json").put("size",count[0]).put("sha256",hex(digest.digest())));
            for(EncryptedBackupArchive.Source original:originals){EncryptedBackupArchive.checkCancelled();String path="originals/"+original.path;ZipEntry entry=new ZipEntry(path);entry.setTime(0);zip.putNextEntry(entry);String before=EncryptedBackupArchive.sha256(original.file);MessageDigest sha=MessageDigest.getInstance("SHA-256");long size;try(InputStream input=new FileInputStream(original.file)){size=EncryptedBackupArchive.copy(input,zip,sha,original.file.length());}zip.closeEntry();if(size!=original.file.length()||!before.equals(hex(sha.digest())))throw new IOException("PORTABLE_SOURCE_CHANGED");entries.put(new JSONObject().put("path",path).put("size",size).put("sha256",before));}
            JSONObject manifest=new JSONObject().put("formatVersion",1).put("kind","hausgarten.portable.business.export").put("captured_at",metadata.getString("capturedAt")).put("schema_version",metadata.getInt("schemaVersion")).put("database_sha256",metadata.getJSONObject("database").getString("sha256")).put("business_id",metadata.getString("businessId")).put("backup_id",metadata.getString("backupId")).put("counts",metadata.getJSONObject("counts")).put("file_manifest",entries).put("plaintext",true).put("csv_encoding","UTF-8").put("csv_dialect","RFC4180 comma CRLF").put("csv_formula_protection","Text cells beginning with formula-significant characters receive a leading apostrophe;business.json and revier.json preserve original values").put("restorable_database_backup",false).put("completion","COMPLETE");
            ZipEntry last=new ZipEntry("manifest.json");last.setTime(0);zip.putNextEntry(last);zip.write(manifest.toString().getBytes(StandardCharsets.UTF_8));zip.closeEntry();return manifest;
        }
    }
    static JSONObject verify(File file,JSONObject expectedMetadata)throws Exception {
        try(ZipFile zip=new ZipFile(file,StandardCharsets.UTF_8)){
            ZipEntry header=zip.getEntry("manifest.json");if(header==null||header.getSize()<1||header.getSize()>EncryptedBackupArchive.MAX_MANIFEST_BYTES)throw new IOException("PORTABLE_MANIFEST_INVALID");JSONObject manifest;
            try(InputStream input=zip.getInputStream(header);ByteArrayOutputStream output=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=input.read(b))!=-1){if(n>EncryptedBackupArchive.MAX_MANIFEST_BYTES-output.size())throw new IOException("PORTABLE_MANIFEST_INVALID");output.write(b,0,n);}manifest=new JSONObject(new String(output.toByteArray(),StandardCharsets.UTF_8));}
            if(manifest.optInt("formatVersion")!=1||!manifest.optString("kind").equals("hausgarten.portable.business.export")||!manifest.optString("completion").equals("COMPLETE")||!manifest.optBoolean("plaintext")||manifest.getInt("schema_version")!=expectedMetadata.getInt("schemaVersion")||!manifest.getString("captured_at").equals(expectedMetadata.getString("capturedAt"))||!manifest.getString("backup_id").equals(expectedMetadata.getString("backupId"))||!manifest.getString("business_id").equals(expectedMetadata.getString("businessId"))||!manifest.getString("database_sha256").equals(expectedMetadata.getJSONObject("database").getString("sha256"))||!PixelMcpWriteTools.hash(manifest.getJSONObject("counts")).equals(PixelMcpWriteTools.hash(expectedMetadata.getJSONObject("counts"))))throw new IOException("PORTABLE_MANIFEST_BINDING_MISMATCH");
            Set<String> names=new HashSet<>();names.add("manifest.json");JSONArray files=manifest.getJSONArray("file_manifest");for(int i=0;i<files.length();i++){JSONObject item=files.getJSONObject(i);String name=item.getString("path");if(!names.add(name))throw new IOException("PORTABLE_DUPLICATE_ENTRY");ZipEntry entry=zip.getEntry(name);if(entry==null||entry.isDirectory()||entry.getSize()!=item.getLong("size"))throw new IOException("PORTABLE_ENTRY_MISSING_OR_CHANGED");MessageDigest digest=MessageDigest.getInstance("SHA-256");long size=0;try(InputStream input=zip.getInputStream(entry)){byte[] b=new byte[65536];int n;while((n=input.read(b))!=-1){EncryptedBackupArchive.checkCancelled();if(n>item.getLong("size")-size)throw new IOException("PORTABLE_ENTRY_SIZE_MISMATCH");digest.update(b,0,n);size+=n;}}if(size!=item.getLong("size")||!hex(digest.digest()).equals(item.getString("sha256")))throw new IOException("PORTABLE_ENTRY_HASH_MISMATCH");}
            Set<String> actual=new HashSet<>();Enumeration<? extends ZipEntry> entries=zip.entries();while(entries.hasMoreElements()){String name=entries.nextElement().getName();if(!actual.add(name))throw new IOException("PORTABLE_DUPLICATE_ENTRY");}if(!actual.equals(names)||!actual.contains("business.json")||!actual.contains("revier.json"))throw new IOException("PORTABLE_FILE_SET_MISMATCH");return manifest;
        }
    }
    static String csv(JSONArray rows)throws Exception {
        TreeSet<String> fields=new TreeSet<>();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);for(Iterator<String> keys=row.keys();keys.hasNext();)fields.add(keys.next());}
        ArrayList<String> columns=new ArrayList<>();if(fields.remove("id"))columns.add("id");columns.addAll(fields);StringBuilder output=new StringBuilder();line(output,new ArrayList<Object>(columns));for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);ArrayList<Object> values=new ArrayList<>();for(String key:columns)values.add(row.opt(key));line(output,values);}return output.toString();
    }
    private static void line(StringBuilder output,List<Object> values){for(int i=0;i<values.size();i++){if(i>0)output.append(',');Object value=values.get(i);String text=value==null||value==JSONObject.NULL?"":String.valueOf(value);if(value instanceof String&&formula(text))text="'"+text;output.append('"').append(text.replace("\"","\"\"")).append('"');}output.append("\r\n");}
    private static boolean formula(String text){if(text.isEmpty())return false;int i=0;while(i<text.length()&&Character.isWhitespace(text.charAt(i)))i++;char c=i<text.length()?text.charAt(i):text.charAt(0);return c=='='||c=='+'||c=='-'||c=='@'||text.charAt(0)=='\t'||text.charAt(0)=='\r'||text.charAt(0)=='\n';}
    private static void text(ZipOutputStream zip,String path,String text,JSONArray entries)throws Exception {byte[] bytes=text.getBytes(StandardCharsets.UTF_8);ZipEntry entry=new ZipEntry(path);entry.setTime(0);zip.putNextEntry(entry);zip.write(bytes);zip.closeEntry();entries.put(new JSONObject().put("path",path).put("size",bytes.length).put("sha256",hex(MessageDigest.getInstance("SHA-256").digest(bytes))));}
    static boolean allowedBusinessKey(String key){return key.startsWith("revier:v1:")||key.startsWith("local_payment:")||key.startsWith("local_invoice_sources:")||key.startsWith("local_invoice_material_sources:")||key.startsWith("invoice_opening_balance:")||key.startsWith("local_number_reservation:")||key.startsWith("local_invoice_job:")||key.startsWith("local_invoice_reconciliation:")||key.startsWith("local_invoice_document_recovery:")||key.equals("local_invoice_counter")||key.equals("local_invoice_external_evidence");}
    private static String hex(byte[] value){StringBuilder output=new StringBuilder();for(byte b:value)output.append(String.format(Locale.ROOT,"%02x",b&255));return output.toString();}
    private BackupPortableFormat(){}
}
